import re
from dataclasses import dataclass, field
from typing import Optional

# "## [2.4.0] - 2024-05-02" or "## [Unreleased]" (no date).
HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")

# An HTML comment (single- or multi-line), together with the spaces before it and,
# when nothing else follows it on its last line, the spaces after it.
COMMENT = re.compile(r"[ \t]*<!--.*?-->(?:[ \t]*(?=\n|\Z))?", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    """Return the changelog text with maintainer comments removed and LF line endings."""
    return COMMENT.sub("", text.replace("\r\n", "\n"))


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).split("\n"):
        if line.startswith("## "):
            match = HEADING.match(line)
            if match:
                current = Release(match.group("version"), match.group("date"))
                releases.append(current)
            else:
                # Some other level-2 heading ends the release section above it.
                current = None
        elif current is not None:
            current.body.append(line)
    return releases


def _clean_body(lines):
    out = []
    for line in lines:
        if line.strip() == "":
            # Collapse runs of blank lines to one, and drop leading blank lines.
            if out and out[-1] != "":
                out.append("")
        else:
            out.append(line)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            header = f"# {release.version}"
            if release.date:
                header += f" ({release.date})"
            body = _clean_body(release.body)
            return f"{header}\n\n{body}\n" if body else f"{header}\n"
    raise LookupError(version)

